//! Replays `fixtures/wire.jsonl`, generated by `rust/tools/generate_vcs_wire_fixtures.mjs`:
//! JSON encoded by the original contract schemas. Every row must decode into the Rust type
//! and encode back to the same JSON, which fixes field names, optionality, `Option` tagging
//! and timestamp formatting.
use serde::{Serialize, de::DeserializeOwned};
use serde_json::{Value, json};
use t3_vcs::{
    GitCommandError,
    core::GitCommandFailureReason,
    git::{
        VcsDriverCapabilities, VcsFreshness, VcsListRemotesResult, VcsListWorkspaceFilesResult,
        VcsRepositoryIdentity,
    },
    status::VcsStatus,
    wire::{
        ReviewDiffFileContentsInput, ReviewDiffFileContentsResult, ReviewDiffPreviewInput,
        ReviewDiffPreviewResult, VcsListRefsInput, VcsListRefsResult, VcsPullResult,
        VcsStatusLocalResult, VcsStatusRemoteResult,
    },
};

fn rows(kind: &str) -> Vec<Value> {
    include_str!("fixtures/wire.jsonl")
        .lines()
        .map(|line| serde_json::from_str::<Value>(line).unwrap())
        .filter(|row| row["type"] == kind)
        .map(|row| row["json"].clone())
        .collect()
}

fn round_trips<T: Serialize + DeserializeOwned>(kind: &str, expected_rows: usize) {
    let rows = rows(kind);
    assert_eq!(rows.len(), expected_rows, "{kind}");
    for json in rows {
        let value: T = serde_json::from_value(json.clone())
            .unwrap_or_else(|error| panic!("{kind}: {error}: {json}"));
        assert_eq!(serde_json::to_value(&value).unwrap(), json, "{kind}");
    }
}

#[test]
fn driver_results_encode_as_the_original_schemas_do() {
    round_trips::<VcsFreshness>("freshness", 3);
    round_trips::<VcsDriverCapabilities>("capabilities", 2);
    round_trips::<VcsRepositoryIdentity>("repositoryIdentity", 2);
    round_trips::<VcsListWorkspaceFilesResult>("workspaceFiles", 1);
    round_trips::<VcsListRemotesResult>("remotes", 1);
}

#[test]
fn ref_and_status_results_encode_as_the_original_schemas_do() {
    round_trips::<VcsListRefsResult>("listRefsResult", 2);
    round_trips::<VcsPullResult>("pull", 2);
    round_trips::<VcsStatusLocalResult>("statusLocal", 3);
    round_trips::<VcsStatusRemoteResult>("statusRemote", 2);
    round_trips::<VcsStatus>("status", 2);
}

#[test]
fn review_results_encode_as_the_original_schemas_do() {
    round_trips::<ReviewDiffPreviewResult>("reviewPreview", 2);
    round_trips::<ReviewDiffFileContentsResult>("reviewContents", 1);
}

#[test]
fn inputs_decoded_by_the_original_schemas_decode_and_re_encode_unchanged() {
    round_trips::<VcsListRefsInput>("listRefsInput", 2);
    round_trips::<ReviewDiffPreviewInput>("reviewPreviewInput", 3);
    round_trips::<ReviewDiffFileContentsInput>("reviewContentsInput", 6);
}

#[test]
fn git_command_errors_encode_as_the_original_schema_does() {
    let rows = rows("gitCommandError");
    assert_eq!(rows.len(), 3);
    for json in rows {
        let optional = |name: &str| json[name].as_u64().map(|value| value as usize);
        let reason = json["reason"].as_str().map(|reason| match reason {
            "remote_unreachable" => GitCommandFailureReason::RemoteUnreachable,
            "not_a_repository" => GitCommandFailureReason::NotARepository,
            other => panic!("unmapped reason {other}"),
        });
        let error = GitCommandError {
            operation: json["operation"].as_str().unwrap().into(),
            command: json["command"].as_str().unwrap().into(),
            cwd: json["cwd"].as_str().unwrap().into(),
            argument_count: optional("argumentCount"),
            exit_code: json["exitCode"].as_i64().map(|code| code as i32),
            stdout_length: optional("stdoutLength"),
            stderr_length: optional("stderrLength"),
            output_length: optional("outputLength"),
            reason,
            detail: json["detail"].as_str().unwrap().into(),
            cause: None,
        };
        assert_eq!(serde_json::to_value(&error).unwrap(), json);
    }
}

#[test]
fn the_cause_of_an_error_never_reaches_the_wire() {
    let error = GitCommandError {
        cause: Some(std::sync::Arc::new(std::io::Error::other(
            "secret path /home/x",
        ))),
        ..GitCommandError::new("op", std::path::Path::new("/repo"), &[], "d")
    };
    let encoded = serde_json::to_value(&error).unwrap();
    assert_eq!(
        encoded,
        json!({"_tag":"GitCommandError","operation":"op","command":"git","cwd":"/repo","argumentCount":0,"detail":"d"})
    );
}
